type Msg = { type: 'add'; n: number } | { type: 'get'; reply: (n: number) => void };

function assertNever(x: never): never { throw new Error(`unknown message: ${x}`); }

class Counter {
  private count = 0;
  private readonly mailbox: Msg[] = [];
  private draining = false;
  tell(msg: Msg): void { this.mailbox.push(msg); if (!this.draining) this.drain(); }

  private drain(): void {
    this.draining = true;
    try {
      for (let m = this.mailbox.shift(); m; m = this.mailbox.shift()) {
        switch (m.type) {
          case 'add': this.count += m.n; break;
          case 'get': m.reply(this.count); break;
          default: assertNever(m);
        }
      }
    } finally { this.draining = false; }
  }
}
